from devtools.resources.filesystem.models.markdown.heading import MarkdownHeading
from devtools.resources.filesystem.models.markdown.section import MarkdownSection
from devtools.resources.filesystem.models.text import TextFile


@dataclass(frozen=True, slots=True)
class MarkdownFile(TextFile):
    """Represent immutable Markdown source with structural access.

    The model currently recognizes ATX headings only. Headings inside fenced
    code blocks are ignored.

    :ivar content: Original decoded Markdown source.
